const snippets={"Python": ["from typing import List", "", "class Solution:", "", "    def nextPermutation(self, nums: List[int]) -> None:", "        n = len(nums)", "        i = n - 2", "        while i >= 0 and nums[i] >= nums[i + 1]:", "            i -= 1", "        if i >= 0:", "            j = n - 1", "            while nums[j] <= nums[i]:", "                j -= 1", "            (nums[i], nums[j]) = (nums[j], nums[i])", "        (j, k) = (i + 1, n - 1)", "        while j < k:", "            (nums[j], nums[k]) = (nums[k], nums[j])", "            j += 1", "            k -= 1"], "Java": ["import java.util.*;", "class Solution {", "    public void nextPermutation(int[] nums) {", "        int n = nums.length;", "        int i = n - 2;", "        for (; i >= 0; --i) {", "            if (nums[i] < nums[i + 1]) {", "                break;", "            }", "        }", "        if (i >= 0) {", "            for (int j = n - 1; j > i; --j) {", "                if (nums[j] > nums[i]) {", "                    swap(nums, i, j);", "                    break;", "                }", "            }", "        }", "", "        for (int j = i + 1, k = n - 1; j < k; ++j, --k) {", "            swap(nums, j, k);", "        }", "    }", "", "    private void swap(int[] nums, int i, int j) {", "        int t = nums[j];", "        nums[j] = nums[i];", "        nums[i] = t;", "    }", "}"]};
